# A scripted wall clock: reads real elapsed time, except that at
# elapsed=10s an NTP step correction moves it by `step` seconds.
def make_wall(step):
    def wall(elapsed):
        return elapsed + (step if elapsed >= 10 else 0)
    return wall

for name, step in [("clock steps BACK 120s at t=10", -120),
                   ("clock steps FORWARD 120s at t=10", 120)]:
    wall = make_wall(step)
    start_wall = wall(0)
    deadline = start_wall + 30
    print(f"{name}: deadline is wall {deadline:.0f}")
    t = 0
    while True:
        w = wall(t)
        if w >= deadline:
            print(f"  timeout fires at real elapsed {t}s (wall reads {w:.0f})")
            break
        if t in (10, 30, 60, 120):
            print(f"  real {t:3d}s: wall reads {w:6.0f}, elapsed by wall {w - start_wall:6.0f}s")
        t += 5

from datetime import date, timedelta

anchor = date(2024, 2, 29)

def add_year_clamp(d, anchor_day):
    try:
        return date(d.year + 1, d.month, anchor_day)
    except ValueError:
        return date(d.year + 1, d.month, 28)   # clamp to Feb 28

def add_year_roll(d):
    try:
        return date(d.year + 1, d.month, d.day)
    except ValueError:
        return date(d.year + 1, 3, 1)          # roll forward to Mar 1

p1, p2, p3 = anchor, anchor, anchor
print(f"  {'year':6s} {'+365 days':12s} {'calendar, clamp':16s} {'calendar, roll'}")
for y in range(2025, 2029):
    p1 = p1 + timedelta(days=365)
    p2 = add_year_clamp(p2, 29)
    p3 = add_year_roll(p3)
    print(f"  {y:6d} {p1.isoformat():12s} {p2.isoformat():16s} {p3.isoformat()}")

from datetime import datetime, timezone

SPAN_START = datetime(2025, 1, 1, tzinfo=timezone.utc).timestamp()
SPAN_END = datetime(2028, 1, 1, tzinfo=timezone.utc).timestamp()

values = [1735689600, 1767225600, 1767225600000, 1767225600000000,
          1798761600, 1798761600000, 12345678901, 999999999999]

def classify(v):
    if 1e9 <= v < 1e11:
        return "seconds", v
    if 1e12 <= v < 1e14:
        return "milliseconds", v / 1e3
    if 1e15 <= v < 1e17:
        return "microseconds", v / 1e6
    return None, None

for v in values:
    unit, secs = classify(v)
    if unit is None:
        print(f"  {v:>18}  no unit band fits -> QUARANTINE")
        continue
    instant = datetime.fromtimestamp(secs, tz=timezone.utc)
    if SPAN_START <= secs < SPAN_END:
        print(f"  {v:>18}  {unit:12s} -> {instant:%Y-%m-%d %H:%M}Z  ok")
    else:
        print(f"  {v:>18}  {unit:12s} -> {instant:%Y-%m-%d %H:%M}Z  OUT OF SPAN -> review")

from datetime import date

samples = ["03/04/2026", "17/04/2026", "04/17/2026", "12/11/2026",
           "31/01/2026", "01/31/2026", "05/06/2026", "28/02/2026",
           "02/28/2026", "10/10/2026", "07/08/2026", "25/12/2026",
           "12/25/2026", "09/09/2026"]

def try_parse(a, b):
    try:
        return date(2026, a, b)
    except ValueError:
        return None

counts = {"US only": 0, "EU only": 0, "ambiguous": 0, "same either way": 0}
for s in samples:
    parts = s.split("/")
    x, y = int(parts[0]), int(parts[1])
    as_us = try_parse(x, y)   # month=x, day=y
    as_eu = try_parse(y, x)   # day=x, month=y
    if as_us and as_eu:
        if as_us == as_eu:
            counts["same either way"] += 1
            print(f"  {s}  -> {as_us} (identical under both)")
        else:
            counts["ambiguous"] += 1
            print(f"  {s}  -> AMBIGUOUS: {as_us} (US) or {as_eu} (EU)")
    elif as_us:
        counts["US only"] += 1
        print(f"  {s}  -> {as_us} (only parses month-first)")
    else:
        counts["EU only"] += 1
        print(f"  {s}  -> {as_eu} (only parses day-first)")
print()
print(" ", counts)

from datetime import datetime, timezone
from zoneinfo import ZoneInfo

DENVER = ZoneInfo("America/Denver")
UTC = ZoneInfo("UTC")
repaired, quarantined = [], []

# --- epoch rows: classify by magnitude band ---
for rid, v in [("R1", 1767225600), ("R2", 1769904000000),
               ("R3", 999999999999), ("R4", 1772323200)]:
    if 1e9 <= v < 1e11:
        repaired.append((rid, datetime.fromtimestamp(v, tz=UTC), "epoch seconds"))
    elif 1e12 <= v < 1e14:
        repaired.append((rid, datetime.fromtimestamp(v / 1e3, tz=UTC), "epoch milliseconds"))
    else:
        quarantined.append((rid, "no unit band fits"))

# --- string rows: provable formats only ---
def parse_as(s, fmt):
    try:
        return datetime.strptime(s, fmt).date()
    except ValueError:
        return None

for rid, s in [("R5", "17/03/2026"), ("R6", "03/17/2026"),
               ("R7", "05/06/2026"), ("R8", "25/03/2026")]:
    us, eu = parse_as(s, "%m/%d/%Y"), parse_as(s, "%d/%m/%Y")
    if us and not eu:
        repaired.append((rid, us, "US format, provable"))
    elif eu and not us:
        repaired.append((rid, eu, "EU format, provable"))
    else:
        quarantined.append((rid, "ambiguous numeric date"))

# --- naive rows: convert by writer's zone ---
for rid, ts, writer in [("R9", "12:20", "denver"), ("R10", "18:45", "utc"),
                        ("R11", "13:05", None), ("R12", "11:58", "denver")]:
    if writer is None:
        quarantined.append((rid, "writer unknown, zone unknowable"))
        continue
    naive = datetime.strptime("2026-03-14 " + ts, "%Y-%m-%d %H:%M")
    zone = DENVER if writer == "denver" else UTC
    repaired.append((rid, naive.replace(tzinfo=zone).astimezone(UTC),
                     f"naive, {writer} writer"))

print("REPAIRED:")
for rid, val, rule in repaired:
    print(f"  {rid}: {val}   [{rule}]")
print(f"\nQUARANTINED ({len(quarantined)}):")
for rid, why in quarantined:
    print(f"  {rid}: {why}")
print(f"\n{len(repaired)} repaired, {len(quarantined)} quarantined, 12 accounted for")

from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo

NY = ZoneInfo("America/New_York")
start = datetime(2027, 3, 14, 6, 30, tzinfo=timezone.utc)
events = [start + timedelta(minutes=30 * i) for i in range(7)]

monitor = {e.astimezone(NY).strftime("%H:%M"): e for e in events}
fixed = {(e - timedelta(hours=5)).strftime("%H:%M"): e for e in events}

print("  rendered  monitor (zoneinfo)   app (fixed -5)")
for e in events:
    print(f"    {e:%H:%M}Z   {e.astimezone(NY).strftime('%H:%M')} "
          f"{e.astimezone(NY).tzname():4s}            "
          f"{(e - timedelta(hours=5)).strftime('%H:%M')}")

print("\n  join on the rendered string:")
for key in sorted(set(monitor) | set(fixed)):
    m, f = monitor.get(key), fixed.get(key)
    if m and f and m == f:
        print(f"    {key}: same instant - true match")
    elif m and f:
        print(f"    {key}: FALSE match - monitor means {m:%H:%M}Z, app means {f:%H:%M}Z")
    elif f:
        print(f"    {key}: app-only - analyst reads this as a MISSING event")
    else:
        print(f"    {key}: monitor-only - no app row joins to it")
